solution.ConfigException.java:
class ConfigException extends Exception {
    private final int line;

    ConfigException(int line, String message) {
        this(line, message, null);
    }

    ConfigException(int line, String message, Throwable cause) {
        super("line " + line + ": " + message, cause);
        this.line = line;
    }

    int line() { return line; }
}

solution.Config.java:
import java.util.*;

class Config {
    static Map<String, String> parse(List<String> lines) throws ConfigException {
        Objects.requireNonNull(lines, "lines");
        Map<String, String> result = new LinkedHashMap<>();
        int n = 0;
        for (String raw : lines) {
            n++;
            String line = raw.trim();
            if (line.isEmpty() || line.startsWith("#")) continue;
            String[] parts = line.split("=", -1);
            if (parts.length != 2) throw new ConfigException(n, "expected key = value");
            String key = parts[0].trim(), value = parts[1].trim();
            if (!key.matches("[A-Za-z0-9._]+")) throw new ConfigException(n, "bad key");
            if (result.containsKey(key)) throw new ConfigException(n, "duplicate key " + key);
            result.put(key, value);
        }
        return result;
    }

    static int getInt(Map<String, String> config, String key, int min, int max) throws ConfigException {
        String text = config.get(key);
        if (text == null) throw new ConfigException(0, "missing " + key);
        int value;
        try {
            value = Integer.parseInt(text);
        } catch (NumberFormatException e) {
            throw new ConfigException(0, key + " is not a number", e);
        }
        if (value < min || value > max) throw new ConfigException(0, key + " must be between " + min + " and " + max);
        return value;
    }
}

unitTests:
List<String> sample = List.of("# server settings", "port = 8080", "", "host=example.org", "  debug = true  ");

test("parsing", () -> {
    Map<String, String> c = Config.parse(sample);
    checkEq(new ArrayList<>(c.keySet()), List.of("port", "host", "debug"));
    checkEq(c.get("host"), "example.org");
    checkEq(c.get("debug"), "true");
    checkEq(Config.parse(List.of("empty.value =")).get("empty.value"), "");
});

test("errors carry line numbers", () -> {
    String[][] cases = {
        {"port 8080", "line 1: expected key = value"},
        {"a = b = c", "line 1: expected key = value"},
        {" = 5", "line 1: bad key"},
        {"my key = 5", "line 1: bad key"},
    };
    for (String[] c : cases) {
        try {
            Config.parse(List.of(c[0]));
            check(false, "should throw for " + c[0]);
        } catch (ConfigException e) {
            checkEq(e.getMessage(), c[1]);
        }
    }
    try {
        Config.parse(List.of("# x", "a = 1", "", "a = 2"));
        check(false, "should throw");
    } catch (ConfigException e) {
        checkEq(e.getMessage(), "line 4: duplicate key a");
        checkEq(e.line(), 4);
    }
    checkThrows(NullPointerException.class, () -> Config.parse(null));
});

test("reading numbers", () -> {
    Map<String, String> c = Config.parse(List.of("port = 8080", "workers = many", "retries = 99"));
    checkEq(Config.getInt(c, "port", 1, 65535), 8080);
    try {
        Config.getInt(c, "workers", 1, 64);
        check(false, "should throw");
    } catch (ConfigException e) {
        checkEq(e.getMessage(), "line 0: workers is not a number");
        check(e.getCause() instanceof NumberFormatException, "keep the NumberFormatException as the cause");
    }
    checkThrows(ConfigException.class, () -> Config.getInt(c, "retries", 0, 10));
    checkThrows(ConfigException.class, () -> Config.getInt(c, "timeout", 0, 10));
    check(!RuntimeException.class.isAssignableFrom(ConfigException.class), "ConfigException should be a checked exception");
});

